pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        // Ensure the external call doesn't revert by making caddress a simple token that always succeeds
        vm.assume(caddress != address(0) && caddress != address(c));
        // Deploy a dummy token that always returns true on transferFrom
        // We'll use a simple contract that just returns true
        // To avoid extra contracts, we can use vm.mockCall to make any call to caddress return success
        vm.mockCall(caddress, abi.encodeWithSelector(bytes4(keccak256("transferFrom(address,address,uint256)")), from, address(0), v), abi.encode(true));
        // Now call transfer, which should succeed and return true
        bool result = c.transfer(from, caddress, _tos, v);
        assertTrue(result == true, "transfer should return true when all calls succeed");
    }
}

