// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(0) && caddress != address(c) && caddress != address(this));
        vm.deal(caddress, 1 ether);
        bytes memory dummyCode = type(NoFallback).creationCode;
        address noFallback;
        assembly {
            noFallback := create(0, add(dummyCode, 0x20), mload(dummyCode))
        }
        if (caddress == noFallback) vm.assume(false);
        vm.assume(caddress != address(this));
        vm.assume(caddress != address(c));
        (bool success, ) = address(c).call(abi.encodeWithSignature("transfer(address,address,address[],uint256)", from, caddress, _tos, v));
        assertTrue(!success, "reference C should revert when any call to transferFrom fails");
    }
}

contract NoFallback {
    fallback() external payable {
        revert();
    }
}

